/// <summary>
/// PricingAttribute of table <c>InventTable</c> field IntrastatCommodity.
/// </summary>
[UPSPricingMetadataDiscovery][UPSPricingAttributeSourceDiscovery(UPSPricingAttributeSource::Product, UPSPricingAttributeSourceLevel::Line)]
internal class UPSPricingAttributeInventTableIntrastatCommodity extends UPSPricingAttributeInventTable implements UPSIPricingAttribute
{
}

Method.Source:
public str getName()
{
    return fieldPName(InventTable, IntrastatCommodity);
}

public Set getAllowedValues()
{
    var ret = new Set(Types::Int64);
    InventTable inventTable;
    while select IntrastatCommodity from inventTable
        group by IntrastatCommodity
    {
        ret.add(inventTable.IntrastatCommodity);
    }
    return ret;
}

protected void setQueryBuildDatasourceRange(QueryBuildDataSource _qbds, anytype _value)
{
    QueryBuildRange qbr;

    qbr = _qbds.addRange(fieldNum(InventTable, IntrastatCommodity));
    qbr.value(queryValue(_value));
}
